<?php
namespace App\Http\Requests\HumanCapital\Time;
use Illuminate\Foundation\Http\FormRequest;
final class SaveLeaveRequest extends FormRequest { public function authorize():bool{return true;} public function rules():array{return ['employee_id'=>['required','integer','exists:employees,id'],'leave_type_id'=>['required','integer','exists:leave_types,id'],'start_date'=>['required','date'],'end_date'=>['required','date','after_or_equal:start_date'],'total_days'=>['required','numeric','gt:0','max:366'],'total_hours'=>['nullable','numeric','min:0'],'reason'=>['required','string','max:3000'],'attachment'=>['nullable','file','max:10240']];} public function withValidator($validator):void{$validator->after(function($validator):void{if($this->filled('start_date')&&$this->filled('end_date')&&substr((string)$this->input('start_date'),0,4)!==substr((string)$this->input('end_date'),0,4))$validator->errors()->add('end_date','One leave request cannot cross calendar years.');$type=\App\Models\HumanCapital\Time\LeaveType::find($this->integer('leave_type_id'));if($type?->requires_attachment&&!$this->hasFile('attachment'))$validator->errors()->add('attachment','Attachment is required for this leave type.');});} }
